alter table public.access_requests add column if not exists email text;
create or replace function public.submit_access_request(_role public.app_role,_full_name text,_organization_name text default null,_phone text default null,_notes text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare actor uuid:=auth.uid(); actor_email text; target_company uuid; request_id uuid; company_count integer; begin if actor is null then raise exception 'برای ثبت درخواست ابتدا وارد حساب شوید'; end if; if _role not in ('staff'::public.app_role,'customer'::public.app_role,'supplier'::public.app_role,'driver'::public.app_role) then raise exception 'این نقش از مسیر درخواست عمومی قابل دریافت نیست'; end if; if length(trim(coalesce(_full_name,'')))<2 or length(trim(_full_name))>160 then raise exception 'نام باید بین ۲ تا ۱۶۰ نویسه باشد'; end if; if _role in ('customer'::public.app_role,'supplier'::public.app_role) and length(trim(coalesce(_organization_name,'')))<2 then raise exception 'برای این نقش وارد کردن نام کسب‌وکار یا مزرعه الزامی است'; end if; if exists(select 1 from public.memberships m where m.user_id=actor and m.active) then raise exception 'این حساب از قبل عضویت فعال دارد'; end if; select u.email into actor_email from auth.users u where u.id=actor; if actor_email is null then raise exception 'ایمیل حساب احراز هویت‌شده پیدا نشد'; end if; select count(*) into company_count from public.companies; if company_count<>1 then raise exception 'مجموعه مقصد باید از طریق راه‌اندازی مدیر مشخص شود'; end if; select c.id into target_company from public.companies c limit 1; select r.id into request_id from public.access_requests r where r.company_id=target_company and r.user_id=actor and r.status='pending' limit 1; if request_id is not null then update public.access_requests set email=actor_email where id=request_id and email is null; return request_id; end if; insert into public.access_requests(company_id,user_id,email,requested_role,full_name,organization_name,phone,notes) values(target_company,actor,actor_email,_role,trim(_full_name),nullif(trim(coalesce(_organization_name,'')),''),nullif(trim(coalesce(_phone,'')),''),nullif(trim(coalesce(_notes,'')),'')) returning id into request_id; return request_id; end $$;
revoke all on function public.submit_access_request(public.app_role,text,text,text,text) from public,anon; grant execute on function public.submit_access_request(public.app_role,text,text,text,text) to authenticated;
